const EventEmitter = require("events");

/**
 * CroxyDB public entrypoint.
 * @module croxydb
 */

/**
 * @typedef {"jsondb"|"yamldb"|"localstorage"|"mongo"|"mysql"|"firebase"} CroxyAdapterName
 */

/**
 * @typedef {Object} CroxySetOptions
 * @property {number|Date} [ttl] Time to live. A number is treated as milliseconds from now.
 */

/**
 * @typedef {Object} CroxyWebPanelOptions
 * @property {string} [title="CroxyDB Panel"] Browser title and panel heading.
 * @property {string|null} [password] Password used by the login screen.
 * @property {string|null} [token] Bearer token or cookie token. Takes priority over password.
 * @property {boolean} [readonly=false] Blocks write actions when true.
 * @property {number} [pollingInterval=1200] Event polling interval in milliseconds.
 * @property {Object} [actions] Feature flags for panel actions.
 * @property {boolean} [actions.import=true] Enables JSON import.
 * @property {boolean} [actions.export=true] Enables JSON export.
 * @property {boolean} [actions.deleteAll=true] Enables delete-all.
 * @property {Object} [theme] Panel theme colors.
 * @property {string} [theme.primary] Primary accent color.
 * @property {string} [theme.background] Page background color.
 * @property {string} [theme.surface] Panel surface color.
 * @property {string} [theme.muted] Muted text color.
 * @property {string} [theme.text] Main text color.
 */

/**
 * @typedef {Object} CroxyDBOptions
 * @property {CroxyAdapterName} [adapter="jsondb"] Adapter to use.
 * @property {string} [folder="croxydb"] JSON/YAML database folder.
 * @property {string} [file="croxydb"] JSON/YAML database file name without extension.
 * @property {boolean|CroxyWebPanelOptions} [webPanel=false] Enables the built-in web panel.
 * @property {CroxyWebPanelOptions} [webPanelOptions] Web panel options.
 * @property {number} [webPort=2229] Web panel port.
 * @property {boolean} [noBlankData=false] Legacy option. Empty parent objects are now cleaned after deletes.
 * @property {boolean} [readable=false] Pretty-prints JSON files.
 * @property {boolean} [checkUpdates=true] Checks npm for newer CroxyDB versions during operations.
 * @property {string} [seperator="."] Path separator used by nested keys.
 * @property {string|null} [encryptionKey] Enables AES-256-GCM encryption for JSON storage.
 * @property {Object} [mongoOptions] Mongo adapter options.
 * @property {Object} [mysqlOptions] MySQL adapter options.
 * @property {Object} [firebaseOptions] Firebase adapter options.
 * @property {Object} [adapterOptions] Generic adapter-specific options.
 */

/**
 * @callback CroxyMigration
 * @param {CroxyDB} db Database instance.
 * @param {Object} [context] Optional migration context.
 * @returns {void|Promise<void>}
 */

const syncMethods = [
  "set",
  "get",
  "fetch",
  "has",
  "delete",
  "add",
  "subtract",
  "push",
  "unpush",
  "delByPriority",
  "setByPriority",
  "all",
  "deleteAll"
];

function isPromise(value) {
  return value && typeof value.then === "function";
}

function joinPath(prefix, key, seperator) {
  if (!key) return prefix;
  return `${prefix}${seperator}${key}`;
}

/**
 * Main CroxyDB database class.
 *
 * The default module export is a lazy singleton instance. Use
 * `db.createInstance(options)` or `new db.CroxyDB(options)` for isolated databases.
 *
 * @class
 * @extends EventEmitter
 * @example
 * const db = require("croxydb")
 * db.set("user.name", "Ada")
 * db.get("user")
 */
class CroxyDB extends EventEmitter {
  /**
   * Creates a CroxyDB instance.
   * @param {CroxyDBOptions} [options={}] Instance options.
   */
  constructor(options = {}) {
    super();
    this.adapterName = options.adapter || "jsondb";
    this.folder = options.folder;
    this.file = options.file;
    this.webPanel = typeof options.webPanel === "object" ? true : (options.webPanel || false);
    this.webPanelOptions = options.webPanelOptions || (typeof options.webPanel === "object" ? options.webPanel : {});
    this.webPort = options.webPort || this.webPanelOptions.port || 2229;
    this.noBlankData = options.noBlankData || false;
    this.readable = options.readable || false;
    this.mongo = options.adapter === "mongo" || options.mongo || false;
    this.mongoOptions = options.mongoOptions || {};
    this.adapterOptions = options.adapterOptions || options.mysqlOptions || options.firebaseOptions || {};
    this.checkUpdates = options.checkUpdates !== false;
    this.seperator = options.seperator || ".";
    this.encryptionKey = options.encryptionKey || null;
    this.ttl = {};
    this.migrations = [];
    this._checkingUpdate = false;
    this.message = require("../language/en.json");
    if (!options.lazy) {
      this.setOptions();
    }
  }

  /**
   * Rebuilds the active adapter from the current instance options.
   * @returns {true}
   */
  setOptions() {
    const adapterModule = this.mongo
      ? require("../adapters/mongo/index")
      : require(`../adapters/${this.adapterName || "jsondb"}`);

    this.isMongoSpecialSchema = !!this.mongoOptions?.schema;
    this.options = {
      dbName: this.file || "croxydb",
      webPanel: {
        isActive: this.webPanel,
        port: this.webPort
      },
      dbFolder: this.folder || "croxydb",
      noBlankData: this.noBlankData || false,
      readable: this.readable || false,
      isMongo: this.mongo,
      mongoOptions: this.mongoOptions || { seperator: this.seperator || "." },
      isMongoSpecialSchema: this.isMongoSpecialSchema,
      checkUpdates: this.checkUpdates,
      seperator: this.seperator || ".",
      encryptionKey: this.encryptionKey,
      ttl: this.ttl,
      ...this.adapterOptions
    };

    this.message = require("../language/en.json");
    this.options.mongoOptions.seperator = this.options.seperator;
    this.adapter = adapterModule.set ? adapterModule : new adapterModule(this.mongo ? this.options.mongoOptions : this.options);

    if (this.adapter && typeof this.adapter.on === "function") {
      ["set", "delete", "expire", "deleteAll"].forEach((event) => {
        this.adapter.on(event, (...args) => this.emit(event, ...args));
      });
    }

    if (this.webPanel) {
      try {
        const Panel = require("../webpanel/index");
        if (!this.panel || this.panel.port !== this.options.webPanel.port) {
          if (this.panel && typeof this.panel.close === "function") {
            this.panel.close();
          }
          this.panel = new Panel(this.options.webPanel.port, this, this.webPanelOptions);
        }
      } catch (err) {}
    } else if (this.panel && typeof this.panel.close === "function") {
      this.panel.close();
      this.panel = null;
    }

    this.checkForUpdates();
    return true;
  }

  /**
   * Checks npm for a newer CroxyDB version when update checks are enabled.
   * @returns {void}
   */
  checkForUpdates() {
    if (!this.checkUpdates || this._checkingUpdate || typeof fetch !== "function") return;
    this._checkingUpdate = true;
    try {
      fetch("https://registry.npmjs.org/croxydb/latest").then((res) => {
        res.json().then((data) => {
          if (require("../package.json").version !== data.version) {
            console.warn(this.message["errors"]["oldVersion"]);
          }
        }).finally(() => {
          this._checkingUpdate = false;
        });
      }).catch(() => {
        this._checkingUpdate = false;
      });
    } catch (err) {
      this._checkingUpdate = false;
    }
  }

  /**
   * Calls a method on the active adapter.
   * @param {string} method Adapter method name.
   * @param {Array<*>} args Adapter method arguments.
   * @returns {*}
   * @private
   */
  call(method, args) {
    if (!this.adapter) {
      this.setOptions();
    }
    this.checkForUpdates();
    if (!this.adapter || typeof this.adapter[method] !== "function") {
      throw new TypeError(`Adapter does not support ${method}.`);
    }
    return this.adapter[method](...args);
  }

  /**
   * Calls an async method on the active adapter.
   * @param {string} method Adapter method name.
   * @param {Array<*>} args Adapter method arguments.
   * @returns {Promise<*>}
   * @private
   */
  async callAsync(method, args) {
    if (!this.adapter) {
      this.setOptions();
    }
    this.checkForUpdates();
    const asyncMethod = `${method}Async`;
    const fn = this.adapter && (this.adapter[asyncMethod] || this.adapter[method]);
    if (typeof fn !== "function") {
      throw new TypeError(`Adapter does not support ${method}.`);
    }
    return await fn.apply(this.adapter, args);
  }

  /**
   * Enables or disables update checks.
   * @param {boolean} a Pass true to enable checks, false to disable them.
   * @returns {boolean} Current update-check state.
   */
  setCheckUpdates(a) {
    this.checkUpdates = a === true;
    this.setOptions();
    return this.checkUpdates;
  }

  /**
   * Enables or disables the built-in dependency-free web panel.
   * @param {boolean} a Pass true to enable the panel.
   * @param {number|CroxyWebPanelOptions} [port=2229] Port number or panel options.
   * @param {CroxyWebPanelOptions} [options={}] Panel options.
   * @returns {boolean} Current web panel state.
   */
  setWebPanel(a, port = 2229, options = {}) {
    if (typeof port === "object") {
      options = port;
      port = options.port || 2229;
    }
    this.webPanel = a === true;
    this.webPort = port;
    this.webPanelOptions = options || {};
    this.setOptions();
    return this.webPanel;
  }

  /**
   * Sets the nested-key separator.
   * @param {string} a Separator string.
   * @returns {true}
   */
  setSeperator(a) {
    this.seperator = a;
    this.setOptions();
    return true;
  }

  /**
   * Switches the instance back to the JSON adapter from MongoDB.
   * @returns {void}
   */
  deleteMongo() {
    this.adapterName = "jsondb";
    this.mongo = false;
    this.setOptions();
  }

  /**
   * Sets the active storage adapter.
   * @param {CroxyAdapterName} adapter Adapter name.
   * @param {Object} [options] Adapter-specific options.
   * @returns {true|Object} True for most adapters, Mongo adapter instance for MongoDB.
   * @example
   * db.setAdapter("mysql", { host: "localhost", user: "root", database: "app" })
   */
  setAdapter(adapter, options = { seperator: this.seperator }) {
    if (adapter !== "mongo") {
      require(`../adapters/${adapter}`);
      this.adapterName = adapter || "jsondb";
      this.adapterOptions = options || {};
      this.mongo = false;
      this.setOptions();
      return true;
    }

    try {
      require("mongoose");
    } catch (error) {
      throw new TypeError("You must install \"mongoose\" modules to use this adapter.");
    }
    this.adapterName = "mongo";
    this.mongo = true;
    this.mongoOptions = options;
    this.setOptions();
    return this.adapter;
  }

  /**
   * Sets the JSON/YAML database folder.
   * @param {string} folder Folder path.
   * @returns {true}
   */
  setFolder(folder) {
    this.folder = folder;
    this.setOptions();
    return true;
  }

  /**
   * Sets the JSON/YAML database file name without extension.
   * @param {string} file File name.
   * @returns {true}
   */
  setFile(file) {
    this.file = file;
    this.setOptions();
    return true;
  }

  /**
   * Enables or disables pretty JSON output.
   * @param {boolean} boolean Pretty-print JSON when true.
   * @returns {boolean} Current readable state.
   */
  setReadable(boolean) {
    this.readable = boolean ? (typeof boolean === "boolean" ? true : false) : false;
    this.setOptions();
    return this.readable;
  }

  /**
   * Sets the legacy empty-data cleanup option.
   *
   * Empty parent objects are cleaned after deletes regardless of this option.
   * @param {boolean} boolean Cleanup flag.
   * @returns {boolean} Current noBlankData state.
   */
  setNoBlankData(boolean) {
    this.noBlankData = boolean ? (typeof boolean === "boolean" ? boolean : false) : false;
    this.setOptions();
    return this.noBlankData;
  }

  /**
   * Sets the encryption key for JSON storage.
   * @param {string|null} key Secret key, or null to disable encryption for future writes.
   * @returns {true}
   */
  setEncryptionKey(key) {
    this.encryptionKey = key || null;
    this.setOptions();
    return true;
  }

  /**
   * Creates an isolated CroxyDB instance.
   * @param {CroxyDBOptions} [options] Instance options.
   * @returns {CroxyDB}
   */
  createInstance(options) {
    return new CroxyDB(options);
  }

  /**
   * Creates a scoped database API under a key prefix.
   * @param {string} prefix Key prefix.
   * @returns {Object} Scoped API with the same CRUD methods.
   * @example
   * const users = db.path("users")
   * users.set("1.name", "Ada")
   */
  path(prefix) {
    const db = this;
    const scoped = {};
    syncMethods.forEach((method) => {
      scoped[method] = (...args) => {
        if (method === "all" || method === "deleteAll") {
          return db[method](joinPath(prefix, args[0], db.seperator));
        }
        return db[method](joinPath(prefix, args[0], db.seperator), ...args.slice(1));
      };
      scoped[`${method}Async`] = async (...args) => {
        if (method === "all" || method === "deleteAll") {
          return await db[`${method}Async`](joinPath(prefix, args[0], db.seperator));
        }
        return await db[`${method}Async`](joinPath(prefix, args[0], db.seperator), ...args.slice(1));
      };
    });
    scoped.path = (child) => db.path(joinPath(prefix, child, db.seperator));
    scoped.on = (...args) => db.on(...args);
    scoped.off = (...args) => db.off(...args);
    return scoped;
  }

  /**
   * Registers a migration function for later execution.
   * @param {string} name Migration name.
   * @param {CroxyMigration} fn Migration function.
   * @returns {true}
   */
  registerMigration(name, fn) {
    this.migrations.push({ name, fn });
    return true;
  }

  /**
   * Runs registered migrations or the provided migration list.
   * @param {Array<CroxyMigration|{name?: string, fn: CroxyMigration}>} [migrations] Migrations to run.
   * @param {Object} [context={}] Context passed to each migration.
   * @returns {Promise<true>}
   */
  async migrate(migrations, context = {}) {
    const list = Array.isArray(migrations) ? migrations : this.migrations;
    for (const migration of list) {
      if (typeof migration === "function") {
        await migration(this, context);
      } else if (migration && typeof migration.fn === "function") {
        await migration.fn(this, context);
      }
    }
    return true;
  }

  /**
   * Copies all entries from a QuickDB-like instance into the active adapter.
   * @param {{fetchAll: function(): Array<{ID: string, data: *}>}} quickDB QuickDB-compatible instance.
   * @returns {true}
   */
  move(quickDB) {
    console.log("[CroxyDB]: QuickDB to CroxyDB: Started copying database.");
    quickDB.fetchAll().map((data) => {
      this.adapter.set(data.ID, data.data);
      console.log(`[CroxyDB]: QuickDB to CroxyDB: Copied ${data.ID}`);
    });
    return true;
  }

  /**
   * Copies a plain JSON object into the active Mongo adapter.
   * @param {Object} JsonDB Source object.
   * @returns {true}
   */
  moveToMongo(JsonDB) {
    console.log("[CroxyDB]: JsonDB to CroxyDB Mongo Adapter: Started copying database.");
    Object.keys(JsonDB).map(async (data) => {
      await this.adapter.set(data, JsonDB[data]);
      console.log(`[CroxyDB]: JsonDB to CroxyDB Mongo Adapter: Copied ${data}`);
    });
    return true;
  }

  /**
   * Copies Mongo adapter rows into the active JSON adapter.
   * @param {Object} MongoDB Mongo rows keyed by index.
   * @returns {true}
   */
  moveFromMongo(MongoDB) {
    console.log("[CroxyDB]: Croxy Mongo Adapter to JsonDB Adapter: Started copying database.");
    Object.keys(MongoDB).map((data) => {
      this.adapter.set(MongoDB[data].key, MongoDB[data].value);
      console.log(`[CroxyDB]: Croxy Mongo Adapter to JsonDB Adapter: Copied ${MongoDB[data].key}`);
    });
    return true;
  }
}

/**
 * Stores a value by key.
 * @name CroxyDB#set
 * @function
 * @param {string} key Database key.
 * @param {*} value Value to store.
 * @param {CroxySetOptions} [options] Set options.
 * @returns {*}
 */
/**
 * Gets a value by key.
 * @name CroxyDB#get
 * @function
 * @param {string} key Database key.
 * @returns {*|undefined}
 */
/**
 * Alias of {@link CroxyDB#get}.
 * @name CroxyDB#fetch
 * @function
 * @param {string} key Database key.
 * @returns {*|undefined}
 */
/**
 * Checks whether a key exists. Falsey stored values still count as existing.
 * @name CroxyDB#has
 * @function
 * @param {string} key Database key.
 * @returns {boolean}
 */
/**
 * Deletes a key and cleans empty parent objects.
 * @name CroxyDB#delete
 * @function
 * @param {string} key Database key.
 * @returns {boolean}
 */
/**
 * Adds a number to the current numeric value.
 * @name CroxyDB#add
 * @function
 * @param {string} key Database key.
 * @param {number} value Number to add.
 * @returns {number}
 */
/**
 * Subtracts a number from the current numeric value.
 * @name CroxyDB#subtract
 * @function
 * @param {string} key Database key.
 * @param {number} value Number to subtract.
 * @returns {number}
 */
/**
 * Pushes a value into an array.
 * @name CroxyDB#push
 * @function
 * @param {string} key Database key.
 * @param {*} value Value to push.
 * @returns {Array<*>}
 */
/**
 * Removes matching values from an array.
 * @name CroxyDB#unpush
 * @function
 * @param {string} key Database key.
 * @param {*} value Value to remove.
 * @returns {Array<*>}
 */
/**
 * Deletes an array item by one-based priority index.
 * @name CroxyDB#delByPriority
 * @function
 * @param {string} key Database key.
 * @param {number} priority One-based array index.
 * @returns {Array<*>|false}
 */
/**
 * Replaces an array item by one-based priority index.
 * @name CroxyDB#setByPriority
 * @function
 * @param {string} key Database key.
 * @param {*} value Replacement value.
 * @param {number} priority One-based array index.
 * @returns {Array<*>|false}
 */
/**
 * Returns all data, or a scoped value when a key is passed.
 * @name CroxyDB#all
 * @function
 * @param {string} [key] Optional scoped key.
 * @returns {Object|*}
 */
/**
 * Deletes all data, or a scoped key when a key is passed.
 * @name CroxyDB#deleteAll
 * @function
 * @param {string} [key] Optional scoped key.
 * @returns {boolean}
 */
/**
 * Async version of {@link CroxyDB#set}.
 * @name CroxyDB#setAsync
 * @function
 * @param {string} key Database key.
 * @param {*} value Value to store.
 * @param {CroxySetOptions} [options] Set options.
 * @returns {Promise<*>}
 */
/**
 * Async version of {@link CroxyDB#get}.
 * @name CroxyDB#getAsync
 * @function
 * @param {string} key Database key.
 * @returns {Promise<*|undefined>}
 */
/**
 * Async version of {@link CroxyDB#delete}.
 * @name CroxyDB#deleteAsync
 * @function
 * @param {string} key Database key.
 * @returns {Promise<boolean>}
 */
/**
 * Async version of {@link CroxyDB#all}.
 * @name CroxyDB#allAsync
 * @function
 * @param {string} [key] Optional scoped key.
 * @returns {Promise<Object|*>}
 */
syncMethods.forEach((method) => {
  CroxyDB.prototype[method] = function (...args) {
    if (["set", "push", "unpush", "setByPriority"].includes(method) && args.length < 2) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }
    if (method === "all" && args.length > 0) {
      return this.get(args[0]);
    }
    if (method === "deleteAll" && args.length > 0) {
      return this.delete(args[0]);
    }
    const result = this.call(method, args);
    if (isPromise(result)) {
      return result;
    }
    return result;
  };

  CroxyDB.prototype[`${method}Async`] = async function (...args) {
    if (method === "all" && args.length > 0) {
      return await this.getAsync(args[0]);
    }
    if (method === "deleteAll" && args.length > 0) {
      return await this.deleteAsync(args[0]);
    }
    return await this.callAsync(method, args);
  };
});

/**
 * Default lazy singleton instance exported by the package.
 * @type {CroxyDB}
 */
const singleton = new CroxyDB({ lazy: true });

singleton.CroxyDB = CroxyDB;
/**
 * Creates an isolated CroxyDB instance from the singleton export.
 * @param {CroxyDBOptions} [options] Instance options.
 * @returns {CroxyDB}
 */
singleton.createInstance = function (options) {
  return new CroxyDB(options);
};

module.exports = singleton;
